package main

import (
 "strconv"
 "strings"
)
func isClueLine(text string) bool { if text=="" { return false }; for _,c:=range []byte(text) { if c!=' ' && (c<'0' || c>'9') { return false } }; return true }
func parseClue(text string) ([]int,bool) {
 if text=="0" { return []int{},true }; clue:=[]int{}
 for _,token:=range strings.Split(text," ") { if len(token)<1 || len(token)>2 || token[0]=='0' { return nil,false }; for _,c:=range []byte(token) { if c<'0' || c>'9' { return nil,false } }; n,_:=strconv.Atoi(token); clue=append(clue,n) }; return clue,true
}
func runClue(cells []Cell) []int { clue:=[]int{}; run:=0; for _,cell:=range cells { if cell==Filled { run++ } else if run>0 { clue=append(clue,run); run=0 } }; if run>0 { clue=append(clue,run) }; return clue }
func clueText(clue []int,separator string) string { if len(clue)==0 { return "0" }; parts:=make([]string,len(clue)); for i,n:=range clue { parts[i]=strconv.Itoa(n) }; return strings.Join(parts,separator) }
func clueSpan(clue []int) int { sum:=len(clue)-1; for _,n:=range clue { sum+=n }; return sum }
func equalClue(a,b []int) bool { if len(a)!=len(b) { return false }; for i:=range a { if a[i]!=b[i] { return false } }; return true }

package main

type Cell uint8
const ( Unknown Cell=iota; Filled; Empty )
type Grid [][]Cell
type Placements struct { cells []Cell; clue []int; before,after [][]bool }
func fitTable(cells []Cell,clue []int) [][]bool {
 n,k:=len(cells),len(clue); empties:=make([]int,n+1); for i,c:=range cells { empties[i+1]=empties[i]; if c==Empty { empties[i+1]++ } }; table:=make([][]bool,n+1); for i:=range table { table[i]=make([]bool,k+1) }; table[0][0]=true
 for end:=1;end<=n;end++ { for count:=0;count<=k;count++ { fits:=cells[end-1]!=Filled && table[end-1][count]; if !fits && count>0 { start:=end-clue[count-1]; if start>=0 && empties[end]==empties[start] { if start==0 { fits=count==1 } else { fits=cells[start-1]!=Filled && table[start-1][count-1] } } }; table[end][count]=fits } }; return table
}
func placements(cells []Cell,clue []int) Placements { reversed:=make([]Cell,len(cells)); for i,c:=range cells { reversed[len(cells)-1-i]=c }; back:=make([]int,len(clue)); for i,n:=range clue { back[len(clue)-1-i]=n }; return Placements{cells,clue,fitTable(cells,clue),fitTable(reversed,back)} }
func (p Placements) Consistent() bool { return p.before[len(p.cells)][len(p.clue)] }
func (p Placements) Starts(block int) []int {
 starts:=[]int{}; n:=len(p.cells); length:=p.clue[block]
 for start:=0;start+length<=n;start++ { end:=start+length; possible:=true; for _,c:=range p.cells[start:end] { if c==Empty { possible=false; break } }; if !possible { continue }; left:=block==0; if start>0 { left=p.cells[start-1]!=Filled && p.before[start-1][block] }; rest:=len(p.clue)-block-1; right:=rest==0; if end<n { right=p.cells[end]!=Filled && p.after[n-end-1][rest] }; if left && right { starts=append(starts,start) } }; return starts
}
func hasPlacement(cells []Cell,clue []int) bool { return placements(cells,clue).Consistent() }
func solveLine(cells []Cell,clue []int,precise bool) []Cell {
 p:=placements(cells,clue); if !p.Consistent() { return nil }; solved:=append([]Cell(nil),cells...); filled:=make([]bool,len(cells)); covered:=make([]bool,len(cells))
 for block,length:=range clue { starts:=p.Starts(block); if precise { for _,start:=range starts { for i:=start;i<start+length;i++ { filled[i]=true } } } else { low,high:=starts[0],starts[len(starts)-1]; for i:=high;i<low+length;i++ { if solved[i]==Unknown { solved[i]=Filled } }; for i:=low;i<high+length;i++ { covered[i]=true } } }
 for i,c:=range cells { if c!=Unknown { continue }; if precise { emptiable:=false; for k:=0;k<=len(clue);k++ { if p.before[i][k] && p.after[len(cells)-i-1][len(clue)-k] { emptiable=true; break } }; if filled[i] && !emptiable { solved[i]=Filled } else if emptiable && !filled[i] { solved[i]=Empty } } else if solved[i]==Unknown && !covered[i] { solved[i]=Empty } }; return solved
}

package main

import (
 "fmt"
 "os"
 "sort"
 "strconv"
 "strings"
)

type Given struct { row,column int; state Cell }
type Puzzle struct { name string; width,height int; rawRows,rawColumns,answerLines []string; givens []Given; hasAnswer bool; rows,columns [][]int; answer Grid; error string; analysis *Analysis; answerResult string }
type Logical struct { grid Grid; propagation Propagation; result string }
type Analysis struct { simple,logic Logical; search *Search; solutions []Grid; status,difficulty string; lineSolves,guesses,maxDepth int }
func integer(text string) int { n,e:=strconv.Atoi(text); if e!=nil { panic(e) }; return n }
func readBlocks(path string) [][]string {
 data,e:=os.ReadFile(path); if e!=nil { panic(e) }; blocks:=[][]string{}; var block []string
 for _,line:=range strings.Split(strings.TrimSuffix(string(data),"\n"),"\n") { if block==nil { if line!="" && !strings.HasPrefix(line,"#") { block=[]string{line} } } else if line=="END" { blocks=append(blocks,block); block=nil } else { block=append(block,line) } }; return blocks
}
func validName(name string) bool { if len(name)<1 || len(name)>20 { return false }; for _,c:=range []byte(name) { if !(c>='a' && c<='z' || c>='0' && c<='9' || c=='_') { return false } }; return true }
func parsePuzzle(block []string) *Puzzle {
 size:=strings.Split(block[1]," "); p:=&Puzzle{name:strings.TrimPrefix(block[0],"PUZZLE "),width:integer(size[1]),height:integer(size[2]),answerResult:"-"}; at:=3; for block[at]!="COLUMNS" { p.rawRows=append(p.rawRows,block[at]); at++ }; at++
 for at<len(block) && isClueLine(block[at]) { p.rawColumns=append(p.rawColumns,block[at]); at++ }; for at<len(block) && strings.HasPrefix(block[at],"GIVEN ") { fields:=strings.Split(block[at]," "); p.givens=append(p.givens,Given{integer(fields[1])-1,integer(fields[2])-1,charState(fields[3][0])}); at++ }; if at<len(block) { p.hasAnswer=true; p.answerLines=append([]string{},block[at+1:]...) }; return p
}
func (p *Puzzle) Validate(seen map[string]bool) string {
 if !validName(p.name) { return "bad name" }; if seen[p.name] { return "duplicate name" }; if p.width<1 || p.width>30 || p.height<1 || p.height>30 { return "bad size" }; if len(p.rawRows)!=p.height { return fmt.Sprintf("row count %d expected %d",len(p.rawRows),p.height) }; if len(p.rawColumns)!=p.width { return fmt.Sprintf("column count %d expected %d",len(p.rawColumns),p.width) }
 totals:=[2]int{}; for kind,texts:=range [][]string{p.rawRows,p.rawColumns} { label,length:="row",p.width; if kind==1 { label,length="column",p.height }; clues:=[][]int{}; for i,text:=range texts { clue,valid:=parseClue(text); if !valid { return fmt.Sprintf("bad clue %s %d",label,i+1) }; if clueSpan(clue)>length { return fmt.Sprintf("%s %d too long",label,i+1) }; clues=append(clues,clue); for _,n:=range clue { totals[kind]+=n } }; if kind==0 { p.rows=clues } else { p.columns=clues } }; if totals[0]!=totals[1] { return fmt.Sprintf("total mismatch rows=%d columns=%d",totals[0],totals[1]) }
 occupied:=map[[2]int]bool{}; for k,g:=range p.givens { if g.row<0 || g.row>=p.height || g.column<0 || g.column>=p.width || g.state==Unknown { return fmt.Sprintf("bad given %d",k+1) }; cell:=[2]int{g.row,g.column}; if occupied[cell] { return fmt.Sprintf("duplicate given %d",k+1) }; occupied[cell]=true }
 if p.hasAnswer { if len(p.answerLines)!=p.height { return "bad answer" }; for _,line:=range p.answerLines { if len(line)!=p.width { return "bad answer" }; for _,c:=range []byte(line) { if c!='#' && c!='.' && c!='?' { return "bad answer" } } }; p.answer=stateGrid(p.answerLines) }; return ""
}
func stateGrid(lines []string) Grid { grid:=make(Grid,len(lines)); for r,line:=range lines { grid[r]=make([]Cell,len(line)); for c,ch:=range []byte(line) { grid[r][c]=charState(ch) } }; return grid }
func logical(rows,columns [][]int,givens []Given,precise bool) Logical {
 grid:=make(Grid,len(rows)); for r:=range grid { grid[r]=make([]Cell,len(columns)) }; for _,g:=range givens { grid[g.row][g.column]=g.state }; rowMarks,columnMarks:=make([]bool,len(rows)),make([]bool,len(columns)); for i:=range rowMarks { rowMarks[i]=true }; for i:=range columnMarks { columnMarks[i]=true }; p:=propagate(grid,rows,columns,precise,rowMarks,columnMarks); result:="stuck"; if p.conflict>=0 { result="contradiction at="+p.steps[p.conflict].Label() } else if determined(grid)==len(rows)*len(columns) { result="solved" }; return Logical{grid,p,result}
}
func analyze(rows,columns [][]int,givens []Given) *Analysis {
 a:=&Analysis{simple:logical(rows,columns,givens,false),logic:logical(rows,columns,givens,true),difficulty:"-"}; a.lineSolves=len(a.logic.propagation.steps)
 if a.logic.propagation.conflict>=0 { a.status="contradiction" } else if a.logic.result=="solved" { a.status="unique"; a.solutions=[]Grid{a.logic.grid}; a.difficulty="medium"; if a.simple.result=="solved" { a.difficulty="easy" } } else { a.search=&Search{rows:rows,columns:columns}; a.search.Run(a.logic.grid,1); a.solutions=a.search.solutions; a.status=[]string{"none","unique","multiple"}[len(a.solutions)]; if a.status=="unique" { a.difficulty="hard" }; a.lineSolves+=a.search.lineSolves; a.guesses=len(a.search.guesses); a.maxDepth=a.search.maxDepth }; return a
}
func clueStats(rows,columns [][]int) string {
 rowBlocks,columnBlocks,filled,largest,fixed:=0,0,0,0,0
 for kind,clues:=range [][][]int{rows,columns} { length:=len(columns); if kind==1 { length=len(rows) }; for _,clue:=range clues { if kind==0 { rowBlocks+=len(clue); for _,n:=range clue { filled+=n } } else { columnBlocks+=len(clue) }; for _,n:=range clue { largest=max(largest,n) }; if len(clue)==0 || clueSpan(clue)==length { fixed++ } } }; return fmt.Sprintf("row_blocks=%d column_blocks=%d filled=%d max_block=%d fixed_lines=%d",rowBlocks,columnBlocks,filled,largest,fixed)
}
func features(grid Grid) string {
 h,w:=len(grid),len(grid[0]); filled,components,largest:=0,0,0; minR,minC,maxR,maxC:=h,w,-1,-1; visited:=make([][]bool,h); for r:=range visited { visited[r]=make([]bool,w) }; symmetry:=[3]bool{true,true,true}
 for r,row:=range grid { for c,state:=range row { symmetry[0]=symmetry[0] && state==grid[r][w-1-c]; symmetry[1]=symmetry[1] && state==grid[h-1-r][c]; symmetry[2]=symmetry[2] && state==grid[h-1-r][w-1-c]; if state!=Filled { continue }; filled++; minR=min(minR,r); minC=min(minC,c); maxR=max(maxR,r); maxC=max(maxC,c); if visited[r][c] { continue }; components++; queue:=[][2]int{{r,c}}; visited[r][c]=true; for head:=0;head<len(queue);head++ { cell:=queue[head]; for _,offset:=range [][2]int{{-1,0},{1,0},{0,-1},{0,1}} { rr,cc:=cell[0]+offset[0],cell[1]+offset[1]; if rr>=0 && rr<h && cc>=0 && cc<w && !visited[rr][cc] && grid[rr][cc]==Filled { visited[rr][cc]=true; queue=append(queue,[2]int{rr,cc}) } } }; largest=max(largest,len(queue)) } }
 box:="-"; if filled>0 { box=fmt.Sprintf("%d,%d,%d,%d",minR+1,minC+1,maxR+1,maxC+1) }; names:=[]string{}; for i,name:=range []string{"lr","ud","rot180"} { if symmetry[i] { names=append(names,name) } }; sym:="none"; if len(names)>0 { sym=strings.Join(names,",") }; return fmt.Sprintf("filled=%d components=%d largest=%d bbox=%s symmetry=%s",filled,components,largest,box,sym)
}
func numberList(numbers []int) string { if len(numbers)==0 { return "-" }; parts:=make([]string,len(numbers)); for i,n:=range numbers { parts[i]=strconv.Itoa(n) }; return strings.Join(parts,",") }
func differing(a,b Grid) [][2]int { cells:=[][2]int{}; for r,row:=range a { for c,state:=range row { if state!=b[r][c] { cells=append(cells,[2]int{r,c}) } } }; return cells }
func cellList(cells [][2]int) string { parts:=make([]string,len(cells)); for i,cell:=range cells { parts[i]=fmt.Sprintf("%d,%d",cell[0]+1,cell[1]+1) }; return strings.Join(parts," ") }
func without(givens []Given,index int) []Given { result:=make([]Given,0,len(givens)-1); result=append(result,givens[:index]...); return append(result,givens[index+1:]...) }
func grade(p *Puzzle) (string,[]string) {
 answer:=p.answer; rowMismatch,columnMismatch,givenMismatch:=[]int{},[]int{},[]int{}; for r,clue:=range p.rows { if !hasPlacement(answer[r],clue) { rowMismatch=append(rowMismatch,r+1) } }; for c,clue:=range p.columns { if !hasPlacement(lineCells(answer,false,c),clue) { columnMismatch=append(columnMismatch,c+1) } }; occupied:=map[[2]int]bool{}; for k,g:=range p.givens { occupied[[2]int{g.row,g.column}]=true; state:=answer[g.row][g.column]; if state!=Unknown && state!=g.state { givenMismatch=append(givenMismatch,k+1) } }
 known:=determined(answer); result:="correct"; bad:=len(rowMismatch)+len(columnMismatch)+len(givenMismatch)>0; if known<p.width*p.height { result="partial" } else if bad { result="wrong" }; line:=fmt.Sprintf("answer result=%s known=%d rows=%s columns=%s givens=%s",result,known,numberList(rowMismatch),numberList(columnMismatch),numberList(givenMismatch))
 if result=="partial" { extendable:="no"; if !bad { givens:=append([]Given(nil),p.givens...); for r,row:=range answer { for c,state:=range row { if state!=Unknown && !occupied[[2]int{r,c}] { givens=append(givens,Given{r,c,state}) } } }; a:=analyze(p.rows,p.columns,givens); if a.status=="unique" || a.status=="multiple" { extendable="yes" } }; line+=" extendable="+extendable }
 if p.analysis.status=="unique" { differences:=0; for r,row:=range answer { for c,state:=range row { if state!=Unknown && state!=p.analysis.solutions[0][r][c] { differences++ } } }; line+=fmt.Sprintf(" differs=%d",differences) }; lines:=[]string{line}
 for kind,numbers:=range [][]int{rowMismatch,columnMismatch} { for _,n:=range numbers { isRow:=kind==0; var clue []int; if isRow { clue=p.rows[n-1] } else { clue=p.columns[n-1] }; cells:=lineCells(answer,isRow,n-1); suffix:="got="+clueText(runClue(cells),","); if result=="partial" { suffix="cells="+stateString(cells) }; lines=append(lines,fmt.Sprintf("mismatch %s expected=%s %s",lineLabel(isRow,n-1),clueText(clue,","),suffix)) } }; return result,lines
}
func puzzleParagraph(p *Puzzle) []string {
 lines:=[]string{"PUZZLE "+p.name}; if p.error!="" { return append(lines,"error "+p.error) }; a:=p.analysis; lines=append(lines,fmt.Sprintf("size=%dx%d givens=%d status=%s difficulty=%s",p.width,p.height,len(p.givens),a.status,a.difficulty),"clues "+clueStats(p.rows,p.columns),fmt.Sprintf("simple known=%d line_solves=%d result=%s",determined(a.simple.grid),len(a.simple.propagation.steps),a.simple.result),fmt.Sprintf("logic known=%d line_solves=%d result=%s",determined(a.logic.grid),len(a.logic.propagation.steps),a.logic.result))
 productive,idle,best,at:=0,0,0,"-"; for _,step:=range a.logic.propagation.steps { if step.contradiction { continue }; if step.gain>0 { productive++ } else { idle++ }; if step.gain>best { best=step.gain; at=step.Label() } }; lines=append(lines,fmt.Sprintf("steps productive=%d idle=%d best=%d at=%s",productive,idle,best,at)); if p.width*p.height<=49 { lines=append(lines,"trace "+a.logic.propagation.Record()) }
 if a.logic.result=="stuck" { remaining:=[2][]string{}; for kind,n:=range []int{p.height,p.width} { for i:=0;i<n;i++ { unknown:=0; for _,state:=range lineCells(a.logic.grid,kind==0,i) { if state==Unknown { unknown++ } }; if unknown>0 { remaining[kind]=append(remaining[kind],fmt.Sprintf("%d:%d",i+1,unknown)) } } }; lines=append(lines,fmt.Sprintf("stuck rows=%s columns=%s",strings.Join(remaining[0]," "),strings.Join(remaining[1]," "))) }
 if a.status=="contradiction" { step:=a.logic.propagation.steps[a.logic.propagation.conflict]; var clue []int; if step.row { clue=p.rows[step.index] } else { clue=p.columns[step.index] }; lines=append(lines,fmt.Sprintf("conflict line=%s clue=%s cells=%s",step.Label(),clueText(clue,","),stateString(lineCells(a.logic.grid,step.row,step.index)))) }
 if a.search!=nil { s:=a.search; lines=append(lines,fmt.Sprintf("search guesses=%d max_depth=%d backtracks=%d solutions=%d line_solves=%d",len(s.guesses),s.maxDepth,s.backtracks,len(s.solutions),s.lineSolves)); for _,g:=range s.guesses { lines=append(lines,fmt.Sprintf("guess %d depth=%d cell=%d,%d value=%c solves=%d known=%d result=%s",g.number,g.depth,g.row+1,g.column+1,stateChar(g.value),g.solves,g.known,g.result)) } }
 if a.status=="multiple" { cells:=differing(a.solutions[0],a.solutions[1]); lines=append(lines,fmt.Sprintf("differ count=%d cells=%s",len(cells),cellList(cells))) }
 names,grids:=[]string{},[]Grid{}; if a.status=="contradiction" { names=append(names,"partial"); grids=append(grids,a.logic.grid) } else { if a.simple.result=="stuck" { names=append(names,"simple"); grids=append(grids,a.simple.grid) }; if a.logic.result=="stuck" { names=append(names,"logic"); grids=append(grids,a.logic.grid) }; if a.status=="multiple" { names=append(names,"first","second"); grids=append(grids,a.solutions...) } }; if len(names)>0 { lines=append(lines,gridDisplay(names,grids)...) }; if a.status=="unique" { lines=append(lines,"sheet"); lines=append(lines,answerSheet(p.rows,p.columns,a.solutions[0])...); lines=append(lines,"picture "+features(a.solutions[0])) }
 if len(p.givens)>0 && a.status!="multiple" { numbers:=[]int{}; for k:=range p.givens { other:=analyze(p.rows,p.columns,without(p.givens,k)); if a.status=="unique" && other.status=="unique" || a.status!="unique" && (other.status=="unique" || other.status=="multiple") { numbers=append(numbers,k+1) } }; label:="blame"; if a.status=="unique" { label="redundant" }; lines=append(lines,"givens "+label+"="+numberList(numbers)) }
 if p.hasAnswer { result,answerLines:=grade(p); p.answerResult=result; lines=append(lines,answerLines...) }; return lines
}
func joinParagraphs(paragraphs [][]string) []string { lines:=[]string{}; for _,paragraph:=range paragraphs { if len(lines)>0 { lines=append(lines,"") }; lines=append(lines,paragraph...) }; return lines }
func difficultyRank(difficulty string) int { switch difficulty { case "easy":return 0; case "medium":return 1; default:return 2 } }
func processPuzzles() ([]*Puzzle,[]string,[]string) {
 puzzles:=[]*Puzzle{}; paragraphs:=[][]string{}; stats:=[]string{"puzzle,status,difficulty,width,height,givens,simple_known,logic_known,line_solves,guesses,max_depth,solutions,answer"}; seen:=map[string]bool{}; counts:=map[string]int{}; lineSolves,guesses:=0,0; ranking:=[]*Puzzle{}
 for _,block:=range readBlocks("input/puzzles.txt") { p:=parsePuzzle(block); p.error=p.Validate(seen); seen[p.name]=true; puzzles=append(puzzles,p); if p.error!="" { counts["invalid"]++; stats=append(stats,p.name+",invalid"+strings.Repeat(",-",11)) } else { p.analysis=analyze(p.rows,p.columns,p.givens); a:=p.analysis; counts[a.status]++; counts[a.difficulty]++; lineSolves+=a.lineSolves; guesses+=a.guesses; if a.status=="unique" { ranking=append(ranking,p) } }; paragraphs=append(paragraphs,puzzleParagraph(p)); if p.error=="" { a:=p.analysis; stats=append(stats,fmt.Sprintf("%s,%s,%s,%d,%d,%d,%d,%d,%d,%d,%d,%d,%s",p.name,a.status,a.difficulty,p.width,p.height,len(p.givens),determined(a.simple.grid),determined(a.logic.grid),a.lineSolves,a.guesses,a.maxDepth,len(a.solutions),p.answerResult)) } }
 sort.Slice(ranking,func(i,j int)bool { a,b:=ranking[i],ranking[j]; if difficultyRank(a.analysis.difficulty)!=difficultyRank(b.analysis.difficulty) { return difficultyRank(a.analysis.difficulty)<difficultyRank(b.analysis.difficulty) }; x,y:=a.analysis.lineSolves+25*a.analysis.guesses,b.analysis.lineSolves+25*b.analysis.guesses; if x!=y { return x<y }; return a.name<b.name }); ranks:=[]string{"RANKING"}; for i,p:=range ranking { a:=p.analysis; ranks=append(ranks,fmt.Sprintf("rank %d %s %s score=%d size=%dx%d",i+1,p.name,a.difficulty,a.lineSolves+25*a.guesses,p.width,p.height)) }; paragraphs=append(paragraphs,ranks,[]string{fmt.Sprintf("SUMMARY puzzles=%d invalid=%d contradiction=%d none=%d unique=%d multiple=%d easy=%d medium=%d hard=%d line_solves=%d guesses=%d",len(puzzles),counts["invalid"],counts["contradiction"],counts["none"],counts["unique"],counts["multiple"],counts["easy"],counts["medium"],counts["hard"],lineSolves,guesses)}); return puzzles,joinParagraphs(paragraphs),stats
}
func sameClues(p *Puzzle,rows,columns [][]int) bool { if p.error!="" || p.height!=len(rows) || p.width!=len(columns) { return false }; for i,clue:=range rows { if !equalClue(clue,p.rows[i]) { return false } }; for i,clue:=range columns { if !equalClue(clue,p.columns[i]) { return false } }; return true }
func processPictures(puzzles []*Puzzle) []string {
 paragraphs:=[][]string{}; seen:=map[string]bool{}; invalid,unique,lineLogic,hinted,hints:=0,0,0,0,0; blocks:=readBlocks("input/pictures.txt")
 for _,block:=range blocks { name:=strings.TrimPrefix(block[0],"PICTURE "); texts:=block[1:]; reason:=""; if !validName(name) { reason="bad name" } else if seen[name] { reason="duplicate name" } else if len(texts)<1 || len(texts)>30 { reason="bad height" } else { for r,line:=range texts { bad:=len(line)<1 || len(line)>30 || len(line)!=len(texts[0]); for _,c:=range []byte(line) { if c!='#' && c!='.' { bad=true } }; if bad { reason=fmt.Sprintf("bad row %d",r+1); break } } }; seen[name]=true; if reason!="" { invalid++; paragraphs=append(paragraphs,[]string{"# picture "+name+" error "+reason}); continue }
  grid:=stateGrid(texts); rows,columns:=make([][]int,len(grid)),make([][]int,len(grid[0])); for r,row:=range grid { rows[r]=runClue(row) }; for c:=range columns { columns[c]=runClue(lineCells(grid,false,c)) }; duplicate:="-"; for _,p:=range puzzles { if sameClues(p,rows,columns) { duplicate=p.name; break } }; givens:=[]Given{}; a:=analyze(rows,columns,givens); if a.status=="unique" { unique++ }; if a.difficulty=="easy" || a.difficulty=="medium" { lineLogic++ }; lines:=[]string{fmt.Sprintf("# picture %s size=%dx%d %s",name,len(columns),len(rows),features(grid)),"# clues "+clueStats(rows,columns)+" duplicate_of="+duplicate,fmt.Sprintf("# plain status=%s difficulty=%s line_solves=%d guesses=%d",a.status,a.difficulty,a.lineSolves,a.guesses)}
  for a.status=="multiple" { cell:=differing(a.solutions[0],a.solutions[1])[0]; g:=Given{cell[0],cell[1],grid[cell[0]][cell[1]]}; givens=append(givens,g); a=analyze(rows,columns,givens); lines=append(lines,fmt.Sprintf("# hint %d cell=%d,%d value=%c status=%s",len(givens),g.row+1,g.column+1,stateChar(g.state),a.status)) }
  original:=append([]Given(nil),givens...); for _,g:=range original { index:=-1; for k,current:=range givens { if current.row==g.row && current.column==g.column { index=k; break } }; trial:=without(givens,index); other:=analyze(rows,columns,trial); if other.status=="unique" { givens=trial; lines=append(lines,fmt.Sprintf("# drop cell=%d,%d",g.row+1,g.column+1)) } }; a=analyze(rows,columns,givens); added:=0
