 }; paragraphs=append(paragraphs,[]string{fmt.Sprintf("# SUMMARY pictures=%d invalid=%d unique=%d line_logic=%d hinted=%d hints=%d",len(blocks),invalid,unique,lineLogic,hinted,hints)}); return joinParagraphs(paragraphs)
}
